using LigaVolley.Application.Abstractions.Persistence;using LigaVolley.Domain.MatchOfficials;using Microsoft.EntityFrameworkCore;
namespace LigaVolley.Infrastructure.Persistence.Repositories;
internal sealed class MatchOfficialRepository(LigaVolleyDbContext db):IMatchOfficialRepository{public async Task AcquireMatchLockAsync(int id,CancellationToken ct)=>_=await db.Database.SqlQuery<int>($"SELECT match_id AS [Value] FROM dbo.MATCH WITH (UPDLOCK,HOLDLOCK) WHERE match_id={id}").SingleOrDefaultAsync(ct);public async Task<IReadOnlyList<MatchOfficial>> ListAsync(int id,bool tracking,CancellationToken ct){IQueryable<MatchOfficial>q=db.MatchOfficials.Include(x=>x.Referee).ThenInclude(x=>x.Person).ThenInclude(x=>x.AdditionalDocuments);if(!tracking)q=q.AsNoTracking();return await q.Where(x=>x.MatchId==id).ToListAsync(ct);}public Task<MatchOfficial?> GetByIdAsync(int id,CancellationToken ct)=>db.MatchOfficials.AsNoTracking().SingleOrDefaultAsync(x=>x.MatchOfficialId==id,ct);public void Add(MatchOfficial x)=>db.MatchOfficials.Add(x);public void Remove(MatchOfficial x)=>db.MatchOfficials.Remove(x);}
